self.KB_CONTENT["card:779462"]={"id":"card:779462","ty":"card","sourceId":"779462","title":"『生產計劃排程表』的作業目的為何？","ver":"GP4以上","topic":"訂單","keywords":["訂單","生產","計劃","預計"],"y":"explain","answer":"列印排程基準日起，未來一星期預計完工的數量，作為產銷協調會議時預估訂單交期用。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
