self.KB_CONTENT["card:784350"]={"id":"card:784350","ty":"card","sourceId":"784350","title":"『進貨資料拆解賦予資產編號作業』中的『輸入資產名稱 (MB002)』為何？","ver":"GP4以上","topic":"進貨單","keywords":["進貨單","資產","單身","編號"],"y":"other","answer":"* TlistView 中所選擇的品名規格皆相同，則預設進貨單單身之品名資料。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
