self.KB_CONTENT["field:90033"]={"id":"field:90033","ty":"field","sourceId":"90033","title":"狀態","ver":"GP4.0","topic":"","keywords":[],"job":"晶圓進貨單建立作業","code":"","answer":"【狀態】1:Creat 2:Split (分裂,分割的意思) 3:Merge (合併的意思) 4:Hold 5:結案 y:指定結案；說明於IC設計管理系統->批號追蹤管理->『批號資料維護作業』新增批號時，狀態預設=1，但系統允許修改為其他狀態；登打製令，製令確認，會回寫『批號資料維護作業』的狀態為2:Split。其他的狀態無作業會更新。","file":"fields.jsonl"};
