self.KB_CONTENT["field:783470"]={"id":"field:783470","ty":"field","sourceId":"783470","title":"營運分類三管理","ver":"GP4以上","topic":"","keywords":[],"job":"新科目資料建立作業","code":"MA040","answer":"* 請參考營運分類一管理 (MA038)的說明。","file":"fields.jsonl"};
