self.KB_CONTENT["field:780750"]={"id":"field:780750","ty":"field","sourceId":"780750","title":"來源","ver":"GP4以上","topic":"","keywords":[],"job":"資料匯出入欄位設定作業","code":"TF004","answer":"* 指資料來源為「1.欄位資料」或「2.固定資料」。","file":"fields.jsonl"};
