self.KB_CONTENT["field:780123"]={"id":"field:780123","ty":"field","sourceId":"780123","title":"選擇還款日期","ver":"GP4以上","topic":"","keywords":[],"job":"預計還款狀況表","code":"IPS.TG027","answer":"* 可點選(icon)或[F2]日期快手查詢預計還款日期區間。若空白表全部。","file":"fields.jsonl"};
